import{_ as t,o,c as n,a3 as i}from"./chunks/framework.BveOjhN0.js";const g=JSON.parse('{"title":"Major Update","description":"","frontmatter":{"title":"Major Update"},"headers":[],"relativePath":"00.docs/010.getting-started/001.major-update.md","filePath":"00.docs/010.getting-started/001.major-update.md","lastUpdated":1782620269000}'),d={name:"00.docs/010.getting-started/001.major-update.md"};function a(r,e,s,c,l,p){return o(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="v5" tabindex="-1">v5 <a class="header-anchor" href="#v5" aria-label="Permalink to &quot;v5&quot;">​</a></h1><h2 id="core-changes" tabindex="-1">Core Changes <a class="header-anchor" href="#core-changes" aria-label="Permalink to &quot;Core Changes&quot;">​</a></h2><ol><li><strong>Full TypeScript Rewrite</strong>: All APIs now have complete type definitions.</li><li><strong>Dual Module Format Output</strong>: Both CJS and ESM formats are supported.</li><li><strong>Node.js Version Upgrade</strong>: Minimum requirement is Node.js &gt;= 20.19.0.</li><li><strong>Pino Logging System</strong>: More powerful logging capabilities.</li><li><strong>Bundle Registry Mechanism</strong>: Faster startup.</li><li><strong>Async Controller Loading</strong>: Supports ESM dynamic imports, avoiding sync/async concurrency race conditions.</li><li><strong>Main Process Bundling</strong>: Main process code can be bundled like frontend bundles.</li><li><strong>Build Registry Plugin</strong>: Replicates runtime property name mapping logic.</li><li><strong>Comprehensive Build Configuration Enhancement</strong>: Added numerous fine-grained control options.</li><li><strong>Post-Build Independent Transpilation</strong>: Independently transpiles files that cannot be bundled.</li><li><strong>Encryption System Upgrade</strong>: More secure.</li><li><strong>Atomic Resource Move</strong>: Prevents data loss.</li><li><strong>ee-bin Full Upgrade</strong>: Added complete TypeScript type system.</li><li><strong>EventBus Event Isolation</strong>: Lifecycle event optimization.</li><li><strong>ESM-Compatible Config Loading</strong>: Auto-unwraps <code>__esModule</code> format, supports function/class exports.</li><li><strong>Controller Concurrency Safety</strong>: Explicitly guarantees no state pollution between concurrent requests.</li><li><strong>Cross Inter-Process Improvements</strong>: Optimized.</li></ol><h2 id="i-core-architecture-changes" tabindex="-1">I. Core Architecture Changes <a class="header-anchor" href="#i-core-architecture-changes" aria-label="Permalink to &quot;I. Core Architecture Changes&quot;">​</a></h2><h3 id="_1-full-typescript-rewrite" tabindex="-1">1. Full TypeScript Rewrite <a class="header-anchor" href="#_1-full-typescript-rewrite" aria-label="Permalink to &quot;1. Full TypeScript Rewrite&quot;">​</a></h3><p>In v4, <code>ee-core</code> and <code>ee-bin</code> were written entirely in JavaScript (<code>.js</code>). Type definitions were only auto-generated via <code>tsconfig.json</code> with <code>emitDeclarationOnly + allowJs</code> to produce <code>.d.ts</code> files — the source code itself had no type constraints.</p><p>v5 performs a <strong>full TypeScript rewrite</strong> of both core packages. All source files are <code>.ts</code>, with extremely strict compilation settings.</p><p><strong>Impact</strong>:</p><ul><li>All APIs have complete type definitions; IDE intelligent hints are significantly improved</li><li>Compile-time catches implicit <code>any</code>, unchecked index access, optional property misuse, and other common errors</li><li>ESM source code <code>import</code> must include <code>.js</code> extension (<code>NodeNext</code> specification)</li></ul><h3 id="_2-dual-module-format-output-cjs-esm" tabindex="-1">2. Dual Module Format Output (CJS + ESM) <a class="header-anchor" href="#_2-dual-module-format-output-cjs-esm" aria-label="Permalink to &quot;2. Dual Module Format Output (CJS + ESM)&quot;">​</a></h3><p>v4 only outputs CommonJS (<code>require(&#39;ee-core&#39;)</code>). v5 outputs both CJS and ESM formats:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/cjs/   → CommonJS (module: CommonJS)</span></span>
<span class="line"><span>dist/esm/   → ESM      (module: NodeNext)</span></span></code></pre></div><p>The <code>exports</code> field in <code>package.json</code> provides conditional exports for each subpath:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;./app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;import&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./dist/esm/app/index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;require&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./dist/cjs/app/index.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Impact</strong>:</p><ul><li>Developers can directly <code>import { ElectronEgg } from &#39;ee-core&#39;</code> in ESM projects</li><li>CJS projects continue to use <code>const { ElectronEgg } = require(&#39;ee-core&#39;)</code></li><li>The <code>exports</code> mapping of <code>ee-core</code> is <strong>auto-generated</strong> by <code>scripts/gen-exports.js</code>. After adding new subpath modules, run <code>npm run gen-exports</code> to update — no manual editing needed</li></ul><h3 id="_3-node-js-version-requirement-upgrade" tabindex="-1">3. Node.js Version Requirement Upgrade <a class="header-anchor" href="#_3-node-js-version-requirement-upgrade" aria-label="Permalink to &quot;3. Node.js Version Requirement Upgrade&quot;">​</a></h3><p>v5 requires <strong>Node.js &gt;= 20.19.0</strong>.</p><hr><h2 id="ii-ee-core-feature-updates" tabindex="-1">II. ee-core Feature Updates <a class="header-anchor" href="#ii-ee-core-feature-updates" aria-label="Permalink to &quot;II. ee-core Feature Updates&quot;">​</a></h2><h3 id="_4-logging-system-pino-replaces-egg-logger" tabindex="-1">4. Logging System: Pino Replaces egg-logger <a class="header-anchor" href="#_4-logging-system-pino-replaces-egg-logger" aria-label="Permalink to &quot;4. Logging System: Pino Replaces egg-logger&quot;">​</a></h3><p>v4 uses <code>egg-logger</code> (EggLoggers). Log files append <code>-YYYYMMDD</code> suffixes by day, with lazy initialization via <code>Object.defineProperty</code>.</p><p>v5 fully switches to the <strong>Pino</strong> logging system:</p><table tabindex="0"><thead><tr><th>Feature</th><th>v4 (egg-logger)</th><th>v5 (Pino)</th></tr></thead><tbody><tr><td>Logging library</td><td>egg-logger</td><td>pino + pino-roll + pino-pretty</td></tr><tr><td>Rotation policy</td><td>Append suffix by day</td><td>pino-roll: rotate by day/hour</td></tr><tr><td>Dev output</td><td>Custom format</td><td>pino-pretty: configurable color, depth, timestamp</td></tr><tr><td>Timezone</td><td>Fixed UTC</td><td>IANA timezone support (e.g. <code>Asia/Shanghai</code>)</td></tr><tr><td>Log redaction</td><td>None</td><td>Pino redaction (field masking)</td></tr><tr><td>Custom levels</td><td>Fixed</td><td>Configurable custom levels</td></tr><tr><td>Call style</td><td>Standard method call</td><td>Proxy wrapper: supports <code>{obj, msg}</code>, printf <code>(&#39;count: %d&#39;, 42)</code>, concatenation <code>(&#39;msg:&#39;, val)</code> styles</td></tr><tr><td>Safe mode</td><td>None</td><td>Safe mode prevents serialization crashes</td></tr></tbody></table><p><strong>Impact</strong>:</p><ul><li>Log configuration migrates from <code>config.logger</code> egg-logger format to pino format</li><li><code>coreLogger</code>, <code>logger</code>, <code>errorLogger</code> three instances remain, but the underlying implementation is completely different</li><li>Developers need to update custom log configuration</li></ul><h3 id="_5-bundle-mode-registry-mechanism" tabindex="-1">5. Bundle Mode: Registry Mechanism <a class="header-anchor" href="#_5-bundle-mode-registry-mechanism" aria-label="Permalink to &quot;5. Bundle Mode: Registry Mechanism&quot;">​</a></h3><p>This is v5&#39;s most critical architectural addition. v4 loads controllers and configs at runtime via <code>globby</code> filesystem scanning, and bundled apps also depend on filesystem paths.</p><p><strong>Impact</strong>:</p><ul><li>After bundling, all controllers and configs are registered to global variables, no filesystem scanning needed, faster startup</li><li>Lazy getters avoid initialization order issues — controllers do not execute at the registration phase</li><li>Dev mode (unbundled) automatically falls back to filesystem scanning, consistent with v4 behavior</li><li><code>process.env.EE_BUNDLED = &quot;true&quot;</code> identifies bundle mode</li></ul><h3 id="_6-async-controller-loading" tabindex="-1">6. Async Controller Loading <a class="header-anchor" href="#_6-async-controller-loading" aria-label="Permalink to &quot;6. Async Controller Loading&quot;">​</a></h3><p>v4&#39;s <code>ControllerLoader</code> only supports synchronous <code>require()</code> loading. v5 adds an async loading path:</p><ul><li><code>Application.runAsync()</code> → <code>loadControllerAsync()</code> → <code>FileLoader.parseAsync()</code> → <code>import()</code> dynamic loading</li><li>Loading process has a <code>loading</code> flag to prevent sync/async concurrency race conditions</li></ul><p><strong>Impact</strong>:</p><ul><li>ESM projects can use <code>runAsync()</code> to ensure async modules load correctly</li><li>In async loading mode, controller files can be in ESM format</li></ul><h3 id="_7-ipc-dual-model" tabindex="-1">7. IPC Dual Model <a class="header-anchor" href="#_7-ipc-dual-model" aria-label="Permalink to &quot;7. IPC Dual Model&quot;">​</a></h3><p>v5 explicitly defines the <strong>IPC Dual Model</strong>:</p><table tabindex="0"><thead><tr><th>Model</th><th>Renderer Call</th><th>Main Process Registration</th><th>Characteristics</th></tr></thead><tbody><tr><td>send/on</td><td><code>webContents.send</code> / <code>ipcRenderer.send</code></td><td><code>ipcMain.on</code></td><td>Sync, <code>event.returnValue</code> + <code>event.reply</code></td></tr><tr><td>invoke/handle</td><td><code>ipcRenderer.invoke</code></td><td><code>ipcMain.handle</code></td><td>Async, Promise return value, <strong>recommended</strong></td></tr></tbody></table><p>Error propagation adds <code>{__EE_ERROR__: true, message}</code> structured marker.</p><h3 id="_8-http-service-koa-middleware-chain-standardization" tabindex="-1">8. HTTP Service: Koa Middleware Chain Standardization <a class="header-anchor" href="#_8-http-service-koa-middleware-chain-standardization" aria-label="Permalink to &quot;8. HTTP Service: Koa Middleware Chain Standardization&quot;">​</a></h3><p>v5 explicitly <strong>orders</strong> the middleware chain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>errorHandler → preMiddleware → CORS → koa-body → dispatch → postMiddleware</span></span></code></pre></div><p>A new <code>koaConfig</code> configuration section is added; developers can independently configure <code>preMiddleware</code> and <code>postMiddleware</code> arrays.</p><h3 id="_9-child-process-config-passing-argv-replaces-filesystem" tabindex="-1">9. Child Process Config Passing: argv Replaces Filesystem <a class="header-anchor" href="#_9-child-process-config-passing-argv-replaces-filesystem" aria-label="Permalink to &quot;9. Child Process Config Passing: argv Replaces Filesystem&quot;">​</a></h3><p>v5 passes <code>eeConfig</code> via <strong><code>process.argv[2]</code></strong> (JSON stringified and injected by <code>JobProcess</code>). Inside the child process, <code>setConfig()</code> parses and caches it — no filesystem read needed.</p><p><strong>Impact</strong>:</p><ul><li><code>child_process.fork()</code> scenarios in bundled apps are more reliable</li><li>Child processes no longer depend on config file paths</li></ul><h3 id="_10-port-allocation-dual-level-lock-mechanism" tabindex="-1">10. Port Allocation: Dual-Level Lock Mechanism <a class="header-anchor" href="#_10-port-allocation-dual-level-lock-mechanism" aria-label="Permalink to &quot;10. Port Allocation: Dual-Level Lock Mechanism&quot;">​</a></h3><p>v5 introduces an <strong>old + young dual-level lock set</strong> (15-second rotation) to prevent concurrent processes from grabbing the same port.</p><p>It also checks all local network interfaces to avoid assigning already-occupied ports.</p><h3 id="_11-systemsleep-true-sync-blocking" tabindex="-1">11. systemSleep: True Sync Blocking <a class="header-anchor" href="#_11-systemsleep-true-sync-blocking" aria-label="Permalink to &quot;11. systemSleep: True Sync Blocking&quot;">​</a></h3><p>v5 adds the <code>systemSleep(ms)</code> utility function, using <code>Atomics.wait</code> + <code>SharedArrayBuffer</code> for true synchronous blocking (no CPU occupation), with a busy-wait fallback.</p><h3 id="_12-zero-lodash-dependency" tabindex="-1">12. Zero lodash Dependency <a class="header-anchor" href="#_12-zero-lodash-dependency" aria-label="Permalink to &quot;12. Zero lodash Dependency&quot;">​</a></h3><p>v5 completely removes the following npm dependencies, replacing them with lightweight in-house implementations:</p><table tabindex="0"><thead><tr><th>v4 Dependency</th><th>v5 Replacement</th><th>Location</th></tr></thead><tbody><tr><td>lodash.merge</td><td><code>extend.ts</code> (in-house deep merge)</td><td>ee-core, ee-bin shared</td></tr><tr><td>chalk</td><td>ANSI escape code lightweight implementation</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>is-type-of</td><td><code>is.function()</code> / <code>is.class()</code></td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>fs-extra</td><td><code>copyDirSync()</code> in-house implementation</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>debug</td><td><code>createDebug()</code> environment-driven</td><td>ee-bin <code>lib/helpers.ts</code></td></tr><tr><td>egg-logger</td><td>pino system</td><td>ee-core <code>log/</code></td></tr><tr><td>adm-zip</td><td>compressing</td><td>ee-bin <code>incrUpdater</code></td></tr></tbody></table><p><strong>Impact</strong>:</p><ul><li>Package size and security risks significantly reduced</li></ul><hr><h2 id="iii-ee-bin-feature-updates" tabindex="-1">III. ee-bin Feature Updates <a class="header-anchor" href="#iii-ee-bin-feature-updates" aria-label="Permalink to &quot;III. ee-bin Feature Updates&quot;">​</a></h2><h3 id="_13-build-registry-plugin-core-addition" tabindex="-1">13. Build Registry Plugin (Core Addition) <a class="header-anchor" href="#_13-build-registry-plugin-core-addition" aria-label="Permalink to &quot;13. Build Registry Plugin (Core Addition)&quot;">​</a></h3><p>v4&#39;s ee-bin has no esbuild plugin mechanism. Controllers and config files are directly bundled into main.js (or copied verbatim in copy mode).</p><p>v5 adds <strong><code>bundle_registry_plugin.ts</code></strong>, a key component of v5&#39;s bundling architecture:</p><ul><li>Virtual module <code>app:controller-registry</code>: scans the controller directory and generates a registry</li><li>Virtual module <code>app:config-registry</code>: scans the config directory and generates a registry</li><li>Virtual module <code>app:bundle-entry</code>: entry point that loads registries + main.js in sequence</li></ul><p>The <code>computeProperties()</code> function replicates ee-core&#39;s <code>defaultCamelize(caseStyle: &#39;lower&#39;)</code> logic, ensuring build-time and runtime property name mapping consistency.</p><h3 id="_14-comprehensive-build-configuration-enhancement" tabindex="-1">14. Comprehensive Build Configuration Enhancement <a class="header-anchor" href="#_14-comprehensive-build-configuration-enhancement" aria-label="Permalink to &quot;14. Comprehensive Build Configuration Enhancement&quot;">​</a></h3><p>v5&#39;s <code>build.electron</code> (<code>BundleConfig</code> type) adds numerous fine-grained control options:</p><table tabindex="0"><thead><tr><th>Config Item</th><th>v4</th><th>v5</th><th>Description</th></tr></thead><tbody><tr><td><code>external</code></td><td>None</td><td>✅</td><td>User-defined external packages</td></tr><tr><td><code>sourcemap</code></td><td>false (fixed)</td><td><code>false</code> → auto logic</td><td>dev→inline, prod→off; can explicitly set <code>inline</code>/<code>external</code></td></tr><tr><td><code>minify</code></td><td>None</td><td>✅</td><td>Production minification</td></tr><tr><td><code>drop</code></td><td>None</td><td>✅</td><td>Remove <code>console</code>/<code>debugger</code></td></tr><tr><td><code>keepNames</code></td><td>None</td><td>✅</td><td>Preserve function/class names during minification</td></tr><tr><td><code>legalComments</code></td><td>None</td><td>✅</td><td><code>inline</code>/<code>eof</code>/<code>none</code></td></tr><tr><td><code>define</code></td><td>None</td><td>✅</td><td>Compile-time constant injection</td></tr><tr><td><code>copy</code></td><td>None</td><td>✅</td><td>Extra file/directory copying</td></tr><tr><td><code>format</code></td><td>None</td><td>✅</td><td><code>cjs</code>/<code>esm</code>; default <code>cjs</code></td></tr><tr><td>Framework externals</td><td>No explicit list</td><td>✅</td><td>ee-core, ee-bin, electron, better-sqlite3, proxy-agent, pino-roll, pino-pretty</td></tr></tbody></table><p><strong>Impact</strong>:</p><ul><li>Production builds can finely control sourcemap, minification, constant injection, etc.</li><li><code>sourcemap: false</code> is no longer &quot;always off&quot;, but &quot;auto-decide by environment&quot;</li><li><code>format: &#39;esm&#39;</code> mode requires all business code (controllers, services, configs) to be ESM-compatible</li></ul><h3 id="_15-post-build-processing-independent-file-transpilation" tabindex="-1">15. Post-Build Processing: Independent File Transpilation <a class="header-anchor" href="#_15-post-build-processing-independent-file-transpilation" aria-label="Permalink to &quot;15. Post-Build Processing: Independent File Transpilation&quot;">​</a></h3><p>v5&#39;s bundle mode, after bundling, performs <strong>independent esbuild transpilation</strong> on files that cannot be bundled (<code>preload/bridge.js</code>, <code>jobs/</code> directory, user <code>copy</code> config items):</p><ul><li>Script files (<code>.js</code>/<code>.ts</code>) are compiled with <code>bundle: false</code> into Node-loadable CJS <code>.js</code>, preserving runtime <code>require()</code> calls</li><li>Non-script files are copied verbatim</li><li>All transpilation uses <code>_resolveBaseBuildOptions()</code> shared settings, ensuring format consistency with the main bundle</li></ul><p><strong>Impact</strong>:</p><ul><li><code>preload/bridge.js</code> and <code>jobs/</code> files work correctly in bundled environments</li><li>No need to manually handle <code>child_process.fork()</code> path issues</li></ul><h3 id="_16-encryption-system-upgrade" tabindex="-1">16. Encryption System Upgrade <a class="header-anchor" href="#_16-encryption-system-upgrade" aria-label="Permalink to &quot;16. Encryption System Upgrade&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;"><br></th><th>Feature</th><th>v4</th><th>v5</th></tr></thead><tbody><tr><td style="text-align:left;"><code>entryFiles</code></td><td>None</td><td>✅</td><td>Entry files (e.g. <code>main.js</code>) compiled to <code>.jsc</code> then overwritten <code>.js</code> as bytenode loader shell</td></tr><tr><td style="text-align:left;"><code>bytecodeOptions</code></td><td>Fixed <code>electron: true</code></td><td>✅</td><td>Configurable bytenode compile parameters</td></tr><tr><td style="text-align:left;">Safety check</td><td>None</td><td>✅</td><td>Verifies <code>.jsc</code> exists after compilation before deleting <code>.js</code>; throws error and preserves source file if not</td></tr><tr><td style="text-align:left;"><code>silent</code> mode</td><td>None</td><td>✅</td><td>Hides javascript-obfuscator Pro ad output</td></tr><tr><td style="text-align:left;"><code>cleanFiles</code></td><td>None</td><td>✅</td><td>Specifies encryption artifacts to clean</td></tr><tr><td style="text-align:left;"><code>encryptDir</code></td><td>None</td><td>✅</td><td>Custom encryption output directory</td></tr></tbody></table><h3 id="_17-resource-move-atomic-operation" tabindex="-1">17. Resource Move: Atomic Operation <a class="header-anchor" href="#_17-resource-move-atomic-operation" aria-label="Permalink to &quot;17. Resource Move: Atomic Operation&quot;">​</a></h3><p>v5&#39;s <code>move.ts</code> switches to <strong>atomic operation</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Backup target → .bak → Copy source to target → Delete backup</span></span></code></pre></div><p>On copy failure, restores <code>.bak</code> to prevent data loss.</p><h3 id="_18-other-ee-bin-changes" tabindex="-1">18. Other ee-bin Changes <a class="header-anchor" href="#_18-other-ee-bin-changes" aria-label="Permalink to &quot;18. Other ee-bin Changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>v4</th><th>v5</th></tr></thead><tbody><tr><td>esbuild</td><td>0.21.5</td><td>0.28</td></tr><tr><td>commander</td><td>11.0.0</td><td>14</td></tr><tr><td>Compression lib</td><td>adm-zip</td><td>compressing</td></tr><tr><td>Test framework</td><td>None</td><td>Vitest (coverage 90%/85%)</td></tr><tr><td><code>pargv.js</code></td><td>minimist-style parser</td><td>Retained but refactored to TS</td></tr><tr><td>TypeScript types</td><td>None</td><td>Complete <code>BinConfig</code> type system</td></tr><tr><td>Config loading</td><td><code>.js/.cjs/.ts/.json/.json5</code></td><td>Same + ESM default export unwrapping + function/class config factories</td></tr></tbody></table><hr><h2 id="iv-general-changes" tabindex="-1">IV. General Changes <a class="header-anchor" href="#iv-general-changes" aria-label="Permalink to &quot;IV. General Changes&quot;">​</a></h2><h3 id="_19-eventbus-improvements" tabindex="-1">19. EventBus Improvements <a class="header-anchor" href="#_19-eventbus-improvements" aria-label="Permalink to &quot;19. EventBus Improvements&quot;">​</a></h3><p>v5&#39;s <code>EventBus</code> separates lifecycle events and custom events into two independent internal Maps:</p><ul><li><strong>Lifecycle events</strong> (<code>register</code>/<code>emitLifecycle</code>): duplicate registration <strong>overwrites with warning</strong>, async errors <strong>re-thrown</strong></li><li><strong>Custom events</strong> (<code>on</code>/<code>emit</code>): async errors <strong>caught and logged</strong>, no flow interruption</li></ul><p>v4&#39;s EventBus uses the same mechanism for both event types, with no overwrite warnings.</p><h3 id="_20-esm-compatible-config-loading" tabindex="-1">20. ESM-Compatible Config Loading <a class="header-anchor" href="#_20-esm-compatible-config-loading" aria-label="Permalink to &quot;20. ESM-Compatible Config Loading&quot;">​</a></h3><p>v5&#39;s <code>loadFile()</code> / <code>loadFileAsync()</code> adds ESM compatibility:</p><ul><li>Auto-unwraps <code>{__esModule: true, default: fn}</code> format</li><li>Auto-calls config files exporting functions (passing <code>appInfo</code>)</li><li>Directly uses config files exporting classes (no call)</li><li>Async version uses <code>import()</code> for loading</li></ul><h3 id="_21-controller-concurrency-safety" tabindex="-1">21. Controller Concurrency Safety <a class="header-anchor" href="#_21-controller-concurrency-safety" aria-label="Permalink to &quot;21. Controller Concurrency Safety&quot;">​</a></h3><p>v5 explicitly states: each middleware call <strong>creates a new controller instance</strong>, ensuring no state pollution between concurrent requests. The type system also reinforces this constraint in <code>ControllerLoader</code>.</p><h3 id="_22-cross-inter-process-management-improvements" tabindex="-1">22. Cross Inter-Process Management Improvements <a class="header-anchor" href="#_22-cross-inter-process-management-improvements" aria-label="Permalink to &quot;22. Cross Inter-Process Management Improvements&quot;">​</a></h3><p>v5&#39;s <code>Cross</code> class adds at <code>run()</code>:</p><ul><li>Dynamic port allocation (dual-level lock mechanism)</li><li>Duplicate service names auto-append pid suffix to avoid conflicts</li></ul><hr><h2 id="v-migration-notes" tabindex="-1">V. Migration Notes <a class="header-anchor" href="#v-migration-notes" aria-label="Permalink to &quot;V. Migration Notes&quot;">​</a></h2><h3 id="must-adjust" tabindex="-1">Must Adjust <a class="header-anchor" href="#must-adjust" aria-label="Permalink to &quot;Must Adjust&quot;">​</a></h3><ol><li><strong>Node.js version</strong>: Ensure &gt;= 20.19.0</li><li><strong>Log configuration</strong>: Migrate from egg-logger format to pino format (<code>pino-roll</code> rotation, <code>pino-pretty</code> output, etc.)</li><li><strong>ESM import extension</strong>: <code>import</code> in ee-core source code must include <code>.js</code> (NodeNext specification)</li></ol><h3 id="recommended-adjustments" tabindex="-1">Recommended Adjustments <a class="header-anchor" href="#recommended-adjustments" aria-label="Permalink to &quot;Recommended Adjustments&quot;">​</a></h3><ol><li><strong>Build configuration</strong>: Use the new <code>minify</code>, <code>drop</code>, <code>define</code>, <code>sourcemap</code> auto logic etc. to improve production bundle quality</li><li><strong>Encryption configuration</strong>: New <code>entryFiles</code>, <code>bytecodeOptions</code>, <code>silent</code> etc. options allow finer encryption control</li><li><strong>Async controllers</strong>: ESM projects should use <code>runAsync()</code> + <code>loadControllerAsync()</code></li></ol><h3 id="no-adjustment-needed" tabindex="-1">No Adjustment Needed <a class="header-anchor" href="#no-adjustment-needed" aria-label="Permalink to &quot;No Adjustment Needed&quot;">​</a></h3><ul><li>Dev mode controller/config loading falls back to filesystem scanning, consistent with v4 behavior</li><li><code>ElectronEgg</code> entry class, <code>Application</code> singleton, startup flow sequence unchanged</li><li>Three-channel communication (Socket.IO, HTTP, IPC) architecture unchanged</li><li>Child process (ChildJob, ChildPoolJob) API unchanged</li><li>SqliteStorage API unchanged</li></ul>`,104)])])}const h=t(d,[["render",a]]);export{g as __pageData,h as default};
